"""Interfaces for data loading components to reduce coupling."""

import abc
import torch.utils.data


class IDataLoader(abc.ABC):
    """Interface for data loaders."""

    @abc.abstractmethod
    def load_data(self):
        """Return a DataLoader instance."""
        pass

    @abc.abstractmethod
    def __len__(self):
        """Return number of batches."""
        pass


class IDatasetFactory(abc.ABC):
    """Interface for dataset factories."""

    @abc.abstractmethod
    def get_by_name(self, dataset_name, *args, **kwargs):
        """Return a dataset instance by name."""
        pass
